import { WeightControls } from "@/src/components/cockpit/WeightControls";
import { LensPanel } from "@/src/components/cockpit/LensPanel";

// Eine Spalte, drei Schritte von oben nach unten: fragen → Liste springt → Zeile öffnen.
// Warum keine Seitenleiste mehr: Im 2-Minuten-Demo soll das Auge nicht zwischen Kästen springen.
function Cockpit() {
  const params = useSearchParams();
  const c = useCockpit(params.get("scenario"));

  return (
    <main className="mx-auto max-w-[1400px] px-6 py-12 lg:px-10">
      <CockpitHero scenario={c.selectedScenario} scenarioId={c.scenarioId} />
      <div className="mb-6"><ProductContext scenarioId={c.scenarioId} /></div>

      {c.error && (
        <div role="alert" className="mb-6 border border-[var(--m-red)] bg-white px-4 py-3 text-sm text-[var(--m-red)]">
          {c.error}
        </div>
      )}

      <details className="mb-3 border-b border-[var(--hairline)]">
        <summary className="flex min-h-12 items-center text-sm font-semibold text-[var(--ink)]">Ask a prioritization question</summary>
        <LensPanel
        key={c.scenarioId}
        scenarioId={c.scenarioId}
        applying={c.applying}
        onApply={(weights, question) => c.applyWeights({ ...c.weights, ...weights }, question)}
      />
      </details>

      <WeightControls
        weights={c.weights}
        onChange={c.setWeights}
        applying={c.applying}
        onApply={() => c.applyWeights()}
        onReset={c.resetWeights}
      />

      <section className="mt-6 min-w-0">
        {c.loading && <p className="py-8 text-sm text-[var(--grey-500)]">Loading requirements...</p>}
        {!c.loading && c.requirements.length === 0 && (
          <p className="py-8 text-sm text-[var(--grey-500)]">No requirements for this scenario yet.</p>
        )}
        {!c.loading && c.requirements.length > 0 && (
          <RequirementFilters
            key={c.scenarioId}
            scenarioId={c.scenarioId}
            requirements={c.requirements}
            previousRanks={c.previousRanks}
            highlightRanks={c.highlightRanks}
            conflictTitles={c.conflictTitles}
          />
        )}
      </section>

      {c.toast && (
        <div role="status" className="fixed bottom-24 right-6 z-50 border-l-4 border-[var(--blue)] bg-[var(--black)] px-5 py-3 text-sm text-white">
          {c.toast}
        </div>
      )}
    </main>
  );
}

export default function CockpitPage() {
  // useSearchParams braucht Suspense (Next 16).
  return (
    <Suspense fallback={<main className="px-6 py-12 text-sm text-[var(--grey-500)]">Loading...</main>}>
      <Cockpit />
    </Suspense>
  );
}
"use client";

import type { Scenario } from "@/src/lib/api";
import { getExportUrl } from "@/src/lib/api";
import { getMemoUrl } from "@/src/lib/insights";
import { Button } from "@/src/components/ui/Button";
import { Eyebrow } from "@/src/components/ui/Typography";
import { scenarioLabel } from "@/src/components/shell/scenarioLabel";
import { useAssistant } from "@/src/components/shell/assistant/AssistantProvider";
import { Icon } from "@/src/components/ui/Icon";

export function CockpitHero({ scenario, scenarioId }: { scenario?: Scenario; scenarioId: string }) {
  const assistant = useAssistant();
  const n = scenario?.headline_numbers;
  const stats = n
    ? [
        [(scenario?.data_coverage?.feedback ?? n.evidence).toLocaleString("en-US"), scenario?.data_coverage ? "customer feedback" : "evidence records"],
        [String(n.signals), "findings"],
        [String(n.requirements), "requirements"],
      ]
    : [];
  // Kompakter Kopf: Titel links, Zahlen + Exporte rechts. So stehen Ask-Feld und Rangliste ohne Scrollen im Bild.
  return (
    <header className="grid gap-6 pb-8 lg:grid-cols-[1fr_auto] lg:items-end">
      <div>
        <div className="flex flex-wrap items-center gap-4">
          {/* Guide oben links: Wer das Cockpit zum ersten Mal sieht, findet hier die fünf Schritte, ohne die Seite zu verlassen. */}
          <button
            type="button"
            onClick={() => assistant.open("guide")}
            className="inline-flex items-center gap-2 border border-[var(--hairline)] px-3 py-1.5 text-xs font-semibold text-[var(--ink)] transition-colors hover:border-[var(--ink)]"
          >
            <Icon name="evidence" size={14} /> Guide
          </button>
          <Eyebrow>{scenario ? scenarioLabel(scenario) : "Signal2Spec"}</Eyebrow>
        </div>
        <h1 className="mt-3 text-3xl font-medium">Ranked requirements</h1>
      </div>
      <div className="grid gap-5 lg:justify-items-end">
        <dl className="flex flex-wrap gap-8">
          {stats.map(([value, label]) => (
            <div key={label} className="lg:text-right">
              <dd className="text-3xl font-light tabular-nums text-[var(--ink)]">{value}</dd>
              <dt className="text-[11px] uppercase tracking-[0.12em] text-[var(--grey-500)]">{label}</dt>
            </div>
          ))}
        </dl>
        <div className="flex flex-wrap gap-3">
          <Button variant="outline" href={getMemoUrl(scenarioId)} external className="h-11! px-5! text-sm!">Decision memo</Button>
          <Button variant="outline" href={getExportUrl(scenarioId)} external className="h-11! px-5! text-sm!">Export CSV</Button>
        </div>
      </div>
    </header>
  );
}

